    async fn homolog_rows(db: &Db) -> Vec<(String, String, String)> {
        let conn = db.read().await.unwrap();
        let mut out = Vec::new();
        for row in query_all(
            &conn,
            "SELECT p.body, p.status, j.code FROM proposals p JOIN jurisdictions j ON j.id = p.jurisdiction_id
             WHERE instr(p.body, '[homolog:') > 0",
            (),
        )
        .await
        .unwrap()
        {
            out.push((row.get(0).unwrap(), row.get(1).unwrap(), row.get(2).unwrap()));
        }
        out
    }

    #[tokio::test]
    async fn seeds_every_law_once_in_its_jurisdiction_across_phases() {
        let t = migrated().await;
        catalog::import(&t.db, "catalog/br/jurisdictions.csv")
            .await
            .unwrap();
        let dev = config("development", t.dir.path());
        let dataset = load(Path::new(DATASET)).unwrap();
        seed_homolog(&t.db, &dev, Path::new(DATASET)).await.unwrap();
        let first = homolog_rows(&t.db).await;
        assert_eq!(first.len(), dataset.laws.len());
        for law in &dataset.laws {
            let hits: Vec<_> = first
                .iter()
                .filter(|(b, ..)| b.contains(&marker(law)))
                .collect();
            assert_eq!(hits.len(), 1, "{}", law.id);
            assert_eq!(hits[0].2, law.jurisdiction, "{} jurisdiction", law.id);
            assert!(hits[0].0.contains(&law.url));
        }
        let national: Vec<&str> = first
            .iter()
            .filter(|(.., j)| j == "BR")
            .map(|(_, s, _)| s.as_str())
            .collect();
        for status in ["collecting_signatures", "in_debate", "in_voting"] {
            assert!(national.contains(&status), "national {status}");
        }
        assert!(
            national
                .iter()
                .any(|s| matches!(*s, "approved" | "rejected" | "quorum_not_reached")),
            "a national vote closed with a result"
        );
        let conn = t.db.read().await.unwrap();
        let results: i64 = query_opt(
            &conn,
            "SELECT COUNT(*) FROM vote_results r JOIN proposals p ON p.id = r.proposal_id WHERE instr(p.body, '[homolog:') > 0",
            (),
        )
        .await
        .unwrap()
        .unwrap()
        .get(0)
        .unwrap();
        let expected = dataset
            .laws
            .iter()
            .enumerate()
            .filter(|(_, l)| {
                let pos = dataset
                    .laws
                    .iter()
                    .filter(|o| o.jurisdiction == l.jurisdiction)
                    .position(|o| o.id == l.id)
                    .unwrap();
                Phase::for_index(pos) == Phase::Closed
            })
            .count();
        assert_eq!(results as usize, expected, "every closed vote has a result");
        let open: i64 = query_opt(
            &conn,
            "SELECT COUNT(*) FROM sessions WHERE revoked_at IS NULL",
            (),
        )
        .await
        .unwrap()
        .unwrap()
        .get(0)
        .unwrap();
        assert_eq!(open, 0, "seed sessions are revoked");
        drop(conn);

        let again = seed_homolog(&t.db, &dev, Path::new(DATASET)).await.unwrap();
        assert!(
            again
                .iter()
                .any(|l| l.ends_with(&format!("{} already seeded", dataset.laws.len())))
        );
        assert_eq!(
            homolog_rows(&t.db).await.len(),
            dataset.laws.len(),
            "idempotent"
        );
    }
